using System.ClientModel;
using Azure.AI.OpenAI;
using Azure.Identity;
using OpenAI.Chat;

namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building a minimal
    /// host that reads the connection string from configuration.
    /// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:2
    /// </summary>
    public static IChatClient Create(string connectionName = "chat")
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (dotnet test), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded by CreateApplicationBuilder.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        var host = builder.Build();

        var connStr = host.Services.GetRequiredService<IConfiguration>()
            .GetConnectionString(connectionName);

        if (string.IsNullOrEmpty(connStr))
        {
            throw new InvalidOperationException(
                $"EVAL_USE_REAL_AGENT=1 but ConnectionStrings:{connectionName} is not configured. " +
                "The detected registration (AddAzureOpenAIChatClient) reads connection " +
                $"string \"{connectionName}\" from configuration. Aspire's AppHost " +
                "populates this at runtime, but `dotnet test` runs standalone. " +
                "Wire one of:\n" +
                $"  dotnet user-secrets init --project MyApp.Evals.Tests\n" +
                $"  # Key-based auth:\n" +
                $"  dotnet user-secrets set \"ConnectionStrings:{connectionName}\" " +
                $"\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId={connectionName}\" --project MyApp.Evals.Tests\n" +
                $"  # Entra-ID auth (DefaultAzureCredential):\n" +
                $"  dotnet user-secrets set \"ConnectionStrings:{connectionName}\" " +
                $"\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId={connectionName}\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name.");
        }

        return ParseConnectionString(connStr, connectionName);
    }

    private static IChatClient ParseConnectionString(string connStr, string fallbackDeployment)
    {
        var parts = connStr.Split(';')
            .Select(p => p.Split('=', 2))
            .Where(p => p.Length == 2)
            .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);

        var endpoint = parts.GetValueOrDefault("Endpoint")
            ?? throw new InvalidOperationException("Connection string missing 'Endpoint'.");
